-- PT122-S1-Q17. Batch 10.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch10$PT122-S1-Q17$batch10$ AND q.stimulus=$batch10$Sharon, a noted collector of fine glass, found a rare glass vase in a secondhand store in a small town she was visiting. The vase was priced at $10, but Sharon knew that it was worth at least $1,000. Saying nothing to the storekeeper about the value of the vase, Sharon bought the vase for $10. Weeks later the storekeeper read a newspaper article about Sharon’s collection, which mentioned the vase and how she had acquired it. When the irate storekeeper later accused Sharon of taking advantage of him, Sharon replied that she had done nothing wrong.$batch10$ AND q.prompt=$batch10$Which one of the following principles, if established, most helps to justify Sharon's position?$batch10$ AND q.correct_choice=$batch10$C$batch10$) THEN RAISE EXCEPTION 'Question changed: PT122-S1-Q17'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanation_steps s WHERE s.explanation_id=$batch10$3d8c6c03-0d66-413d-8e4a-86939a92510e$batch10$) <> 0 OR (SELECT COUNT(*) FROM lr_explanation_choice_notes n WHERE n.explanation_id=$batch10$3d8c6c03-0d66-413d-8e4a-86939a92510e$batch10$) <> 5 THEN RAISE EXCEPTION 'Explanation changed: PT122-S1-Q17'; END IF; END $guard$;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e CROSS JOIN (VALUES (0, $batch10$Conclusion$batch10$, $batch10$Sharon did nothing wrong in buying the vase.$batch10$), (1, $batch10$Evidence$batch10$, $batch10$The storekeeper priced the vase at $10 and Sharon paid $10. Sharon knew it was worth at least $1,000 and said nothing.$batch10$), (2, $batch10$Evaluate$batch10$, $batch10$The only thing Sharon did for the storekeeper was pay the asking price. To call that blameless, the principle has to say the buyer's only duty is to pay what the seller asks. Then saying nothing about the value breaks no duty.$batch10$), (3, $batch10$Goal$batch10$, $batch10$A buyer's only obligation is to pay the price the seller asks.$batch10$)) v(position,label,body) WHERE e.id=$batch10$3d8c6c03-0d66-413d-8e4a-86939a92510e$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
